import { Root, Trigger, Content, Portal, PopoverTriggerProps, Arrow, Anchor } from "@radix-ui/react-popover";
import { Measurable } from "@radix-ui/rect";
import { PropsWithChildren, forwardRef, useId, useState } from "react";
import { useModalPortal } from "@/core/components/primitives/modal-portal/modal-portal";
import {
  ButtonProps,
  GhostButton,
  OutlineButton,
  PrimaryButton,
  SecondaryButton,
} from "@/core/components/primitives/parks-button/parks-button";
import { exhaustiveCheck, multipleClassNames } from "@/core/helpers";
import { ESCAPE_KEYS, modalStackManager } from "@/core/helpers/modal-stack-manager";
import { Variants, motion } from "framer-motion";
import styles from "./popover.module.less";

type TriggerButtonProps = { buttonType: "PrimaryButton" | "SecondaryButton" | "GhostButton" | "OutlineButton" } & Omit<
  ButtonProps,
  "onClick"
>;
type Props = {
  triggerButton?: TriggerButtonProps | React.ReactElement;
  contentClassName?: string;
  withArrow?: boolean;
  /**Can be used to control the open state of the popover. Making it a controlled component */
  isOpenOverride?: boolean;
  /**Can be used to control the open state of the popover. Making it a controlled component */
  setIsOpenOverride?: (isOpen: boolean) => void;
  /**Can be used to override the anchor ref. Useful if the Popover should be anchored to something else than the Trigger button*/
  anchorRefOverride?: React.RefObject<Measurable>;
  /**When set to true, interaction with outside elements will be disabled. Used to prevent accidental clicks on other elements when the popover is open */
  asModal?: boolean;
  "data-testid"?: string;
};

const Popover = ({
  triggerButton,
  contentClassName,
  children,
  withArrow,
  isOpenOverride,
  setIsOpenOverride,
  anchorRefOverride,
  asModal = false,
  "data-testid": dataTestId,
}: PropsWithChildren<Props>) => {
  const [isOpen, setIsOpen] = useState(false);
  const modalPortal = useModalPortal();

  const contentVariants = {
    open: {
      opacity: 1,
      y: 0,
    },
    closed: {
      opacity: 0,
      y: -50,
    },
  } satisfies Variants;

  const id = useId();

  return (
    <Root
      open={isOpenOverride ?? isOpen}
      onOpenChange={(newOpenState) => {
        if (setIsOpenOverride) {
          setIsOpenOverride(newOpenState);
        } else {
          setIsOpen(newOpenState);
        }
        if (asModal) {
          if (newOpenState) {
            /**
             * Treat this Popover as a Modal in our system and register that it has been open and should receive key events
             * The Popover from Radix will handle closing itself when the Escape key is pressed,
             * we just need to register so that ModalStackManager know this one is open, and prevent other Modals from handling the Escape while this is open
             */
            modalStackManager.registerNewlyOpenedModal({
              modalKey: id.toString(),
              documentEventListener: (event) => {
                if (ESCAPE_KEYS.has(event.key)) {
                  //Escape key pressed, the popover should close now automatically (Radix handels that)
                  //Now we can unregister this from the stack manager
                  modalStackManager.unregisterClosedModal(id.toString());
                }
              },
            });
          } else {
            modalStackManager.unregisterClosedModal(id.toString());
          }
        }
      }}
      modal={asModal}
    >
      {triggerButton && triggerButtonIsParksButton(triggerButton) && (
        <Trigger asChild>
          <TriggerButton triggerButton={triggerButton} />
        </Trigger>
      )}
      {triggerButton && !triggerButtonIsParksButton(triggerButton) && <Trigger asChild>{triggerButton}</Trigger>}

      {anchorRefOverride && <Anchor virtualRef={anchorRefOverride} />}

      <Portal container={modalPortal}>
        <Content
          className={styles.content}
          sideOffset={5}
          collisionPadding={10}
          align="start"
          asChild
          data-testid={dataTestId}
        >
          <motion.div
            initial="closed"
            animate="open"
            variants={contentVariants}
            className={multipleClassNames(contentClassName)}
          >
            {children}
            {withArrow && <Arrow className={styles.arrow} />}
          </motion.div>
        </Content>
      </Portal>
    </Root>
  );
};

const triggerButtonIsParksButton = (
  triggerButton: NonNullable<Props["triggerButton"]>,
): triggerButton is TriggerButtonProps => "buttonType" in triggerButton;

const TriggerButton = forwardRef<HTMLButtonElement, { triggerButton: TriggerButtonProps } & PopoverTriggerProps>(
  ({ triggerButton, ...rest }, ref) => {
    const { buttonType, ...restOfProps } = triggerButton;

    switch (buttonType) {
      case "PrimaryButton":
        return <PrimaryButton ref={ref} {...restOfProps} {...rest} />;
      case "SecondaryButton":
        return <SecondaryButton ref={ref} {...restOfProps} {...rest} />;
      case "GhostButton":
        return <GhostButton ref={ref} {...restOfProps} {...rest} />;
      case "OutlineButton":
        return <OutlineButton ref={ref} {...restOfProps} {...rest} />;
      default:
        return exhaustiveCheck(buttonType);
    }
  },
);

TriggerButton.displayName = "TriggerButton";

export default Popover;
