import { Meta, StoryObj } from "@storybook/react";
import Popover from "./popover";
import { ReactNode, forwardRef, useRef, useState } from "react";

const meta = {
  title: "Primitives/Popover",
  component: Popover,
} satisfies Meta<typeof Popover>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    triggerButton: {
      buttonType: "GhostButton",
      iconCenterNew: "more-vertical",
    },
    children: <div>Im a child 👶</div>,
    withArrow: false,
  },
};

const CustomNativeButtonComponent = forwardRef<HTMLButtonElement, { children: ReactNode }>(
  ({ children, ...rest }, ref) => {
    return (
      <button ref={ref} {...rest}>
        {children}
      </button>
    );
  },
);

CustomNativeButtonComponent.displayName = "CustomNativeButton";

export const CustomNativeButton: Story = {
  args: {
    ...Primary.args,
    triggerButton: <CustomNativeButtonComponent>Im a custom native button</CustomNativeButtonComponent>,
  },
};

export const ControlledWithDifferentAnchor: Story = {
  render: function Render() {
    const [isOpen, setIsOpen] = useState(false);
    const refToAnchor = useRef<HTMLParagraphElement>(null);

    return (
      <div>
        <p ref={refToAnchor}>Hello! Use me as an anchor</p>
        <Popover withArrow isOpenOverride={isOpen} setIsOpenOverride={setIsOpen} anchorRefOverride={refToAnchor}>
          <div>Im a child 👶</div>
        </Popover>
        <button onClick={() => setIsOpen(!isOpen)}>Use me to controll the thing!</button>
      </div>
    );
  },
};
